import sys
from collections import deque

def min_moves_to_opposite_parity(n, a):
    result = [-1] * n
    visited_odd = [False] * n
    visited_even = [False] * n

    def bfs(start, target_visited):
        queue = deque([(start, 0)])
        while queue:
            pos, moves = queue.popleft()
            if target_visited[pos]:
                return moves
            for next_pos in [pos - a[pos], pos + a[pos]]:
                if 0 <= next_pos < n and not target_visited[next_pos]:
                    target_visited[next_pos] = True
                    queue.append((next_pos, moves + 1))
        return -1

    for i in range(n):
        if a[i] % 2 == 0:
            if not visited_odd[i]:
                visited_odd[i] = True
                result[i] = bfs(i, visited_even)
        else:
            if not visited_even[i]:
                visited_even[i] = True
                result[i] = bfs(i, visited_odd)

    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    result = min_moves_to_opposite_parity(n, a)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
